from __future__ import annotations

from fastapi import APIRouter
from fastapi.responses import HTMLResponse


router = APIRouter(tags=["flow-analysis-ui"])


@router.get("/flow-analysis", response_class=HTMLResponse, include_in_schema=False)
def flow_analysis_ui() -> HTMLResponse:
    """Serve the dependency-free autonomous flow analysis workspace."""

    return HTMLResponse(
        r"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FlowLens · Autonomous journey analysis</title>
  <style>
    :root{--ink:#162033;--muted:#667085;--brand:#3157d5;--brand2:#203ea9;--danger:#b42318;--warn:#b54708;--ok:#067647;--line:#d9deea;--paper:#fff;--soft:#f7f8fc;--bg:#eef1f7;--nav:#101828;--shadow:0 12px 36px #172b4d14}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.48 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}button,input,select,textarea{font:inherit}button{border:0;border-radius:9px;background:var(--brand);color:#fff;padding:10px 14px;font-weight:750;cursor:pointer}button:hover{background:var(--brand2)}button:disabled{cursor:not-allowed;opacity:.55}button.secondary{background:#475467}button.ghost{background:#fff;color:var(--ink);border:1px solid var(--line)}button.danger{background:var(--danger)}a{color:var(--brand)}.topbar{background:var(--nav);color:#fff;padding:14px 24px;display:flex;align-items:center;justify-content:space-between;gap:18px}.brand{font-size:20px;font-weight:850;letter-spacing:-.02em}.brand small{font-size:12px;font-weight:600;color:#aeb8cc;margin-left:8px}.identity{font-size:13px;color:#d0d5dd}.shell{max-width:1280px;margin:auto;padding:30px 22px 70px}.hero{display:flex;justify-content:space-between;align-items:end;gap:28px;margin-bottom:20px}.hero h1{font-size:38px;letter-spacing:-.035em;margin:0 0 8px}.hero p{color:var(--muted);max-width:790px;margin:0}.safety{max-width:360px;background:#fff8eb;border:1px solid #f5cf8f;color:#7a2e0e;border-radius:12px;padding:12px 14px;font-size:13px}.panel{background:var(--paper);border:1px solid var(--line);border-radius:16px;padding:22px;margin:18px 0;box-shadow:var(--shadow)}.panel h2{font-size:21px;margin:0 0 6px}.panel h3{margin:18px 0 8px}.subtle{color:var(--muted);margin:3px 0 16px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(235px,1fr));gap:14px}.grid.two{grid-template-columns:repeat(auto-fit,minmax(340px,1fr))}label{display:block;font-weight:700;color:#344054}label small{display:block;font-weight:500;color:var(--muted)}input,select,textarea{width:100%;padding:10px 11px;border:1px solid #aeb7c7;border-radius:8px;margin:5px 0 9px;background:#fff;color:var(--ink)}input:focus,select:focus,textarea:focus{outline:3px solid #d9e2ff;border-color:var(--brand)}input[type=checkbox]{width:auto;margin-right:7px}.check{font-weight:600;display:flex;align-items:center;margin:8px 0}.actions{display:flex;flex-wrap:wrap;align-items:center;gap:9px;margin-top:12px}.hidden{display:none!important}.statusline{margin:12px 0 0;color:var(--muted);min-height:22px}.statusline.error{color:var(--danger)}details{border-top:1px solid var(--line);margin-top:16px;padding-top:14px}summary{cursor:pointer;font-weight:800}.credential-note{font-size:12px;color:var(--muted)}.stage-wrap{margin-top:16px}.stage-head{display:flex;justify-content:space-between;gap:12px;font-weight:750}.progress{height:10px;background:#e7eaf0;border-radius:99px;overflow:hidden;margin:9px 0}.progress>span{display:block;height:100%;width:0;background:linear-gradient(90deg,#496ce0,#19a974);transition:width .3s}.stages{display:flex;gap:5px;flex-wrap:wrap}.stage{font-size:11px;color:#7b8497;border-radius:99px;background:#edf0f5;padding:3px 7px}.stage.done{color:#05603a;background:#d1fadf}.stage.active{color:#263d93;background:#e0e7ff}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:12px;margin:15px 0}.metric{background:var(--soft);border:1px solid #e7e9f0;border-radius:12px;padding:14px}.metric span{display:block;color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.04em}.metric b{display:block;font-size:25px;margin-top:4px}.badge{display:inline-flex;align-items:center;gap:4px;border-radius:99px;padding:3px 8px;font-size:12px;font-weight:800;background:#e9ecf2;color:#344054;margin:2px}.badge.high,.badge.detected,.badge.regressed{background:#fee4e2;color:#912018}.badge.medium,.badge.candidate,.badge.recommended,.badge.needs_input,.badge.inconclusive{background:#fef0c7;color:#93370d}.badge.low,.badge.optional{background:#e0e7ff;color:#283b8f}.badge.none,.badge.completed,.badge.not_detected,.badge.improved,.badge.auto_report{background:#d1fadf;color:#05603a}.badge.failed,.badge.cancelled{background:#fee4e2;color:#912018}.goal{border:1px solid var(--line);border-radius:13px;padding:17px;margin:14px 0}.goal-head{display:flex;justify-content:space-between;align-items:start;gap:14px}.goal h3{margin:0 0 3px}.goal-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px;margin-top:14px}.path{background:var(--soft);border-radius:10px;padding:13px}.timeline{border-left:3px solid #cad2e4;padding-left:16px;margin:12px 0 4px}.step{position:relative;border:1px solid var(--line);border-radius:9px;padding:10px 12px;background:#fff;margin:9px 0}.step:before{content:"";position:absolute;width:9px;height:9px;border-radius:50%;background:var(--brand);left:-22px;top:15px}.step small{display:block;color:var(--muted);word-break:break-word}.tags{margin-top:6px}.evidence-shot{display:block;width:100%;max-height:210px;object-fit:cover;object-position:top;border:1px solid var(--line);border-radius:7px;margin-top:8px;background:#eef1f7}.confidence{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:7px;margin-top:12px}.conf{border-left:3px solid #9aa9d7;background:#f7f8fc;padding:8px}.conf b{display:block}.limitation{border-left:4px solid #f79009;background:#fffaeb;padding:10px 12px;margin:7px 0;border-radius:4px}.limitation b{display:block}.graph{overflow:auto;border:1px solid var(--line);border-radius:12px;padding:14px;background:#fbfcfe}.graph-lanes{display:grid;grid-template-columns:repeat(3,minmax(220px,1fr));gap:13px;min-width:730px}.lane{background:#f1f4fa;border-radius:10px;padding:10px}.lane h4{margin:0 0 8px;text-transform:capitalize}.node{background:#fff;border:1px solid #cbd3e2;border-radius:8px;padding:9px;margin:7px 0}.node small{display:block;color:var(--muted);word-break:break-all}.node .evidence-shot{max-height:130px}.edge{font-size:12px;border-left:2px solid #98a7cc;margin:6px 0;padding-left:8px;color:#475467}.review-box{border-top:1px solid var(--line);padding-top:13px;margin-top:14px}.history-row,.queue-row,.compare-result{border:1px solid var(--line);border-radius:10px;padding:13px;margin:9px 0}.history-row{display:flex;justify-content:space-between;align-items:center;gap:15px}.history-row p{margin:2px 0}.history-row small{color:var(--muted);word-break:break-all}.review-fields{display:grid;grid-template-columns:180px 160px minmax(220px,1fr);gap:9px;align-items:end}.empty{text-align:center;color:var(--muted);padding:20px}.model-note{font-size:12px;color:var(--muted)}.divider{height:1px;background:var(--line);margin:18px 0}.manual-card{background:var(--soft);border-radius:10px;padding:13px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:760px){.topbar,.hero,.goal-head,.history-row{align-items:stretch;flex-direction:column}.hero h1{font-size:31px}.shell{padding:20px 13px}.panel{padding:16px}.goal-grid,.review-fields{grid-template-columns:1fr}.graph-lanes{grid-template-columns:1fr;min-width:0}}
  </style>
</head>
<body>
  <header class="topbar"><div class="brand">FlowLens <small>autonomous UI audit</small></div><div><span id="identity" class="identity">Not signed in</span> <button id="logoutButton" type="button" class="ghost hidden">Sign out</button></div></header>
  <main class="shell">
    <section class="hero">
      <div><h1>See when leaving is harder than joining.</h1><p>Give the analyzer a URL. It discovers paired acquisition and exit journeys, builds a page-state graph, measures effort, and reports the evidence behind each candidate finding.</p></div>
      <div class="safety"><b>Safe by default.</b> Public websites run in evidence-only mode and stop before mutating, financial, or destructive actions. A stopped journey is inconclusive—not a dark-pattern verdict.</div>
    </section>

    <section class="panel" id="authPanel">
      <h2>Researcher access</h2><p class="subtle">Runs, evidence, reviews, and comparisons are private to your account.</p>
      <div class="grid"><label>Email<input id="email" type="email" autocomplete="username" value="reviewer@example.com"></label><label>Password<input id="password" type="password" autocomplete="current-password"></label></div>
      <div class="actions"><button id="loginButton" type="button">Sign in</button><button id="registerButton" type="button" class="ghost">Create account</button></div><p id="authStatus" class="statusline" aria-live="polite"></p>
    </section>

    <div id="workspace" class="hidden">
      <section class="panel">
        <h2>Start autonomous analysis</h2><p class="subtle">A URL is enough. Select an explicit pair only when you want to focus the search.</p>
        <form id="runForm">
          <div class="grid">
            <label>Website URL<input id="targetUrl" type="url" required placeholder="https://shop.example.com" autocomplete="url"></label>
            <label>Paired goal<select id="goalFamily"><option value="auto">Discover automatically</option><option value="account_create_delete">Create / delete account</option><option value="subscribe_cancel">Subscribe / cancel</option><option value="newsletter_subscribe_unsubscribe">Newsletter opt in / out</option><option value="consent_grant_withdraw">Grant / withdraw consent</option><option value="notifications_enable_disable">Enable / disable notifications</option><option value="integration_connect_disconnect">Connect / disconnect integration</option><option value="payment_method_add_remove">Add / remove payment method</option><option value="loyalty_join_leave">Join / leave loyalty programme</option><option value="data_share_revoke">Enable / revoke data sharing</option><option value="purchase_return">Purchase / initiate return</option></select></label>
            <label>Execution mode<select id="runMode"><option value="evidence_only">Evidence only (public sites)</option><option value="controlled">Controlled test target</option></select><small>Controlled mode is accepted only for explicitly allowed test origins.</small></label>
          </div>
          <label class="check"><input id="analyseModels" type="checkbox" checked>Use BERT and YOLO as supporting evidence</label>
          <label class="check"><input id="analyseBehavior" type="checkbox" checked>Analyze dynamic frontend behaviour (timers, defaults, visual hierarchy, claims and repeated dialogs)</label>
          <details><summary>Optional test credentials</summary><p class="credential-note">Use a disposable test account. Values are sent once, cleared from this form immediately, and never returned by the API.</p><div class="grid"><label>Username or email<input id="testUsername" autocomplete="off"></label><label>Password<input id="testPassword" type="password" autocomplete="new-password"></label><label>One-time code<input id="testOneTimeCode" type="password" autocomplete="one-time-code"><small>Only when the test account already has a current code.</small></label><label>Login URL<input id="loginUrl" type="url" placeholder="https://example.com/login"></label></div></details>
          <details><summary>Exploration limits</summary><div class="grid"><label>Maximum states<input id="maxStates" type="number" min="5" max="60" value="30"></label><label>Maximum depth<input id="maxDepth" type="number" min="1" max="10" value="6"></label><label>Maximum actions<input id="maxActions" type="number" min="5" max="120" value="50"></label><label>Runtime seconds<input id="maxRuntime" type="number" min="30" max="600" value="180"></label><label>Frontend observation seconds<input id="behaviorSeconds" type="number" min="5" max="90" value="30"><small>30–90 seconds is recommended for public timers; local research benchmarks complete in 10 seconds.</small></label><label>Candidates per state<input id="maxCandidates" type="number" min="1" max="15" value="8"></label><label>Replay attempts<input id="replayAttempts" type="number" min="1" max="3" value="2"></label><label>Additional allowed origins<input id="allowedOrigins" placeholder="https://auth.example.com, https://app.example.com"><small>Comma-separated; redirects outside this list are blocked.</small></label></div></details>
          <div class="actions"><button id="runButton" type="submit">Analyze website</button><button id="cancelButton" type="button" class="danger hidden">Cancel run</button></div>
        </form>
        <div id="progressBox" class="stage-wrap hidden" aria-live="polite"><div class="stage-head"><span id="stageLabel">Queued</span><span id="progressLabel">0%</span></div><div class="progress"><span id="progressBar"></span></div><div id="stageList" class="stages"></div><p id="runStatus" class="statusline"></p></div>
        <div id="inputBox" class="hidden"><div class="divider"></div><h3 id="inputTitle">Automation needs assistance</h3><p id="inputMessage" class="subtle"></p><div id="resumeCredentialFields" class="grid"><label>Username<input id="resumeUsername" autocomplete="off"></label><label>Password<input id="resumePassword" type="password" autocomplete="new-password"></label><label>One-time code<input id="resumeOneTimeCode" type="password" autocomplete="one-time-code"></label><label>Login URL<input id="resumeLoginUrl" type="url"></label></div><button id="resumeButton" type="button">Resume securely</button><p id="resumeStatus" class="statusline"></p></div>
      </section>

      <section id="resultPanel" class="panel hidden"><div class="goal-head"><div><h2>Analysis result</h2><p id="resultMeta" class="subtle"></p></div><button type="button" class="ghost" id="refreshResultButton">Refresh</button></div><div id="summaryMetrics" class="metrics"></div><div id="modelStatus"></div><div id="warnings"></div><div id="limitations"></div><div id="behavior"></div><div id="goals"></div><h3>Exploration state graph</h3><p class="subtle">Nodes are distinct observed interface states; edges are attempted actions. Frontier edges show where safe automation stopped.</p><div id="graph" class="graph"></div></section>

      <section class="panel"><div class="goal-head"><div><h2>Autonomous run history</h2><p class="subtle">Open any stored result or select two completed runs for a regression comparison.</p></div><button id="refreshHistoryButton" type="button" class="ghost">Refresh</button></div><div id="historyList"></div></section>

      <section class="panel"><h2>Regression comparison</h2><p class="subtle">Compare matching goal signatures before and after a website change. A regression means the exit became harder or gained obstruction mechanisms.</p><div class="grid"><label>Baseline run<select id="baselineRun"><option value="">Select baseline</option></select></label><label>Candidate run<select id="candidateRun"><option value="">Select candidate</option></select></label></div><button id="compareButton" type="button">Compare runs</button><p id="compareStatus" class="statusline"></p><div id="comparison"></div></section>

      <section class="panel"><div class="goal-head"><div><h2>Confidence-gated review queue</h2><p class="subtle">Only uncertain candidate findings need human review. Confirming a finding validates the evidence; it does not turn this research score into a legal conclusion.</p></div><button id="refreshQueueButton" type="button" class="ghost">Refresh</button></div><div id="reviewQueue"></div></section>

      <section class="panel"><h2>Dynamic frontend research controls</h2><p class="subtle">Load a benchmark into the analyzer, then click Analyze website. These controls test genuine deadlines, resetting urgency, and multiple frontend manipulation signals.</p><div class="grid"><div class="manual-card"><b>Genuine shared deadline</b><p>One server-defined deadline continues across reload and clean sessions.</p><button type="button" class="ghost behavior-preset" data-url="http://127.0.0.1:8000/behavior-benchmarks/genuine-countdown">Load genuine control</button></div><div class="manual-card"><b>Resetting fake countdown</b><p>The countdown restarts and the advertised offer never ends.</p><button type="button" class="secondary behavior-preset" data-url="http://127.0.0.1:8000/behavior-benchmarks/fake-countdown">Load fake timer</button></div><div class="manual-card"><b>Multi-pattern storefront</b><p>Timer, preselection, scarcity, social proof, hidden rejection, nagging and weak subscription disclosure.</p><button type="button" class="danger behavior-preset" data-url="http://127.0.0.1:8000/behavior-benchmarks/manipulative-store">Load pattern showcase</button></div></div></section>

      <section class="panel"><details><summary>Controlled benchmarks and manual paired definitions</summary><p class="subtle">Use these deterministic controls to validate the legacy paired-flow scorer. The URL-first autonomous analyzer above is the primary workflow.</p><div class="grid"><div class="manual-card"><b>Fair local control</b><p>One-step account creation and deletion.</p><button type="button" class="secondary manual-preset" data-path="/api/v1/flow-runs/presets/local/fair">Run control</button></div><div class="manual-card"><b>Obstructed local control</b><p>Forced reason, retention and repeated confirmation.</p><button type="button" class="secondary manual-preset" data-path="/api/v1/flow-runs/presets/local/obstructed">Run control</button></div><div class="manual-card"><b>Manual API</b><p>Submit reviewed paired definitions through the API explorer.</p><a href="/docs" target="_blank" rel="noreferrer">Open API documentation</a></div></div><p id="manualStatus" class="statusline"></p></details></section>
    </div>
  </main>
  <script>
    const $=id=>document.getElementById(id);
    const stages=['queued','validating','static_scan','runtime_analysis','discovering_acquisition','establishing_session','discovering_exit','replaying','scoring','persisting','needs_input','completed'];
    let token=sessionStorage.getItem('flowlens_token')||'', currentRun='', pollTimer=null, completedRuns=[];
    const authHeaders=(json=true)=>Object.assign(json?{'Content-Type':'application/json'}:{},{Authorization:`Bearer ${token}`});
    const escapeHtml=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
    const title=value=>String(value??'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
    const number=(value,digits=1)=>Number(value??0).toFixed(digits).replace(/\.0$/,'');
    async function api(path,options={}){const response=await fetch(path,{...options,headers:{...authHeaders(options.body!==undefined),...(options.headers||{})}});let data=null;try{data=await response.json()}catch{data={detail:response.statusText}}if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail||data));return data}
    function showError(node,error){node.textContent=error instanceof Error?error.message:String(error);node.classList.add('error')}
    function badge(value){return `<span class="badge ${escapeHtml(value)}">${escapeHtml(title(value))}</span>`}
    function metric(label,value){return `<div class="metric"><span>${escapeHtml(label)}</span><b>${escapeHtml(value)}</b></div>`}

    async function authenticate(mode){const status=$('authStatus');status.classList.remove('error');status.textContent=mode==='login'?'Signing in…':'Creating account…';try{const body={email:$('email').value.trim(),password:$('password').value};let data=await api(`/api/v1/auth/${mode}`,{method:'POST',body:JSON.stringify(body),headers:{Authorization:''}});if(mode==='register')data=await api('/api/v1/auth/login',{method:'POST',body:JSON.stringify(body),headers:{Authorization:''}});token=data.access_token;sessionStorage.setItem('flowlens_token',token);$('password').value='';await enterWorkspace()}catch(error){showError(status,error)}}
    async function enterWorkspace(){try{const me=await api('/api/v1/auth/me');$('identity').textContent=me.email;$('logoutButton').classList.remove('hidden');$('authPanel').classList.add('hidden');$('workspace').classList.remove('hidden');await Promise.all([loadHistory(),loadReviewQueue()])}catch{logout('Session expired')}}
    function logout(message='Not signed in'){clearTimeout(pollTimer);token='';currentRun='';sessionStorage.removeItem('flowlens_token');$('identity').textContent=message;$('logoutButton').classList.add('hidden');$('authPanel').classList.remove('hidden');$('workspace').classList.add('hidden')}

    function requestBody(){const username=$('testUsername').value.trim(),password=$('testPassword').value;const credentials=username&&password?{username,password}:null;if(credentials&&$('testOneTimeCode').value)credentials.one_time_code=$('testOneTimeCode').value;if(credentials&&$('loginUrl').value.trim())credentials.login_url=$('loginUrl').value.trim();return {url:$('targetUrl').value.trim(),mode:$('runMode').value,goal_families:[$('goalFamily').value],credentials,allowed_origins:$('allowedOrigins').value.split(',').map(x=>x.trim()).filter(Boolean),analyse_models:$('analyseModels').checked,analyse_behavior:$('analyseBehavior').checked,policy:{max_states:+$('maxStates').value,max_depth:+$('maxDepth').value,max_actions:+$('maxActions').value,max_runtime_seconds:+$('maxRuntime').value,behavior_observation_seconds:+$('behaviorSeconds').value,max_candidates_per_state:+$('maxCandidates').value,replay_attempts:+$('replayAttempts').value}}}
    function clearSecrets(){$('testUsername').value='';$('testPassword').value='';$('testOneTimeCode').value='';$('loginUrl').value='';$('resumeUsername').value='';$('resumePassword').value='';$('resumeOneTimeCode').value='';$('resumeLoginUrl').value=''}
    async function startRun(event){event.preventDefault();const status=$('runStatus');status.classList.remove('error');status.textContent='Submitting URL for safe validation…';$('progressBox').classList.remove('hidden');$('inputBox').classList.add('hidden');try{const job=await api('/api/v1/flow-runs/autonomous',{method:'POST',body:JSON.stringify(requestBody())});clearSecrets();currentRun=job.run_id;updateProgress(job);$('cancelButton').classList.remove('hidden');schedulePoll(250);loadHistory()}catch(error){clearSecrets();showError(status,error)}}
    function schedulePoll(delay=1300){clearTimeout(pollTimer);pollTimer=setTimeout(pollCurrent,delay)}
    async function pollCurrent(){if(!currentRun)return;try{const job=await api(`/api/v1/autonomous-flow-runs/${currentRun}`);updateProgress(job);if(['queued','running'].includes(job.status))schedulePoll();else{clearTimeout(pollTimer);$('cancelButton').classList.add('hidden');if(job.status==='needs_input')configureInput(job.result);if(job.result)renderResult(job.result);loadHistory();loadReviewQueue()}}catch(error){showError($('runStatus'),error)}}
    function configureInput(result){const codes=new Set((result?.limitations||[]).filter(x=>x.recoverable).map(x=>x.code));const credentialUseful=['credentials_required','authentication_failed','mfa_required','email_verification_required'].some(x=>codes.has(x));$('inputBox').classList.remove('hidden');$('resumeCredentialFields').classList.toggle('hidden',!credentialUseful);$('resumeButton').classList.toggle('hidden',!credentialUseful);$('inputTitle').textContent=credentialUseful?'Automation needs test credentials':'Automation reached an external boundary';$('inputMessage').textContent=credentialUseful?'After completing any e-mail or device approval, supply the disposable test account and current one-time code to rerun the journey. Secret values are never persisted.':'Review the recorded limitation below. CAPTCHA, bot protection, identity-provider approval, and rate limits cannot be bypassed by this product; this run remains inconclusive.'}
    function updateProgress(job){$('progressBox').classList.remove('hidden');$('stageLabel').textContent=title(job.stage);$('progressLabel').textContent=`${job.progress}%`;$('progressBar').style.width=`${job.progress}%`;$('runStatus').textContent=`${title(job.status)} · run ${job.run_id}${job.error?` · ${job.error}`:''}`;const active=Math.max(0,stages.indexOf(job.stage));$('stageList').innerHTML=stages.map((item,index)=>`<span class="stage ${index<active?'done':index===active?'active':''}">${escapeHtml(title(item))}</span>`).join('')}
    async function cancelRun(){if(!currentRun)return;try{const job=await api(`/api/v1/autonomous-flow-runs/${currentRun}/cancel`,{method:'POST'});updateProgress(job);clearTimeout(pollTimer);$('cancelButton').classList.add('hidden');loadHistory()}catch(error){showError($('runStatus'),error)}}
    async function resumeRun(){const status=$('resumeStatus'),username=$('resumeUsername').value.trim(),password=$('resumePassword').value;if(!username||!password){showError(status,new Error('Username and password are required.'));return}const credentials={username,password};if($('resumeOneTimeCode').value)credentials.one_time_code=$('resumeOneTimeCode').value;if($('resumeLoginUrl').value.trim())credentials.login_url=$('resumeLoginUrl').value.trim();try{const job=await api(`/api/v1/autonomous-flow-runs/${currentRun}/input`,{method:'POST',body:JSON.stringify({credentials})});clearSecrets();$('inputBox').classList.add('hidden');updateProgress(job);schedulePoll()}catch(error){clearSecrets();showError(status,error)}}

    function renderResult(data){currentRun=data.run_id;$('resultPanel').classList.remove('hidden');$('resultMeta').textContent=`${data.url} · ${data.pipeline_version} · run ${data.run_id}`;const s=data.summary;$('summaryMetrics').innerHTML=metric('Outcome',title(s.outcome))+metric('Confidence',`${Math.round(s.confidence*100)}%`)+metric('Flow candidates',s.roach_motel_candidates)+metric('Behaviour detected',s.behavioral_detected||0)+metric('Behaviour suspicious',s.behavioral_suspicious||0)+metric('Gate',title(s.gate));$('modelStatus').innerHTML=`<p class="model-note">Supporting models: BERT ${badge(data.model_status.bert)} YOLO ${badge(data.model_status.yolo)} · ${escapeHtml(data.model_status.note)}</p>`;$('warnings').innerHTML=(data.warnings||[]).map(x=>`<div class="limitation"><b>Research warning</b>${escapeHtml(x)}</div>`).join('');renderLimitations(data.limitations||[],$('limitations'));renderBehavior(data.frontend_behavior||{status:'not_requested',findings:[]});$('goals').innerHTML=(data.goals||[]).length?(data.goals||[]).map(renderGoal).join(''):'<div class="empty">No comparable paired flow goal was discovered. Dynamic frontend findings above remain independently valid.</div>';renderGraph(data.graph||{nodes:[],edges:[]});hydrateScreenshots($('resultPanel'),data.run_id)}
    function renderBehavior(report){const root=$('behavior'),items=report.findings||[],artifacts=report.artifacts||{},network=artifacts.network_observations||[];if(report.status==='not_requested'){root.innerHTML='';return}const artifactSummary=`<div class="metrics">${metric('DOM snapshots',(report.dom_snapshots||[]).length)}${metric('Network observations',network.length)}${metric('Code excerpts',(artifacts.code_evidence||[]).length)}${metric('Redacted screenshots',(report.screenshots||[]).length)}</div><details><summary>Captured frontend artifact metadata</summary><p class="subtle">Original HTML SHA-256: ${escapeHtml(artifacts.original_html_sha256||'Unavailable')}<br>Rendered DOM SHA-256: ${escapeHtml(artifacts.rendered_dom_sha256||'Unavailable')}</p>${network.slice(0,20).map(x=>`<div class="edge">${escapeHtml(x.method)} ${escapeHtml(x.resource_type)} · ${escapeHtml(x.status??'—')} · ${escapeHtml(x.url)}${x.response_sha256?` · SHA-256 ${escapeHtml(x.response_sha256)}`:''}</div>`).join('')}</details>`;root.innerHTML=`<h3>Dynamic frontend behaviour ${badge(report.status)}</h3><p class="subtle">Observed for ${escapeHtml(report.observation_seconds||0)} seconds, then compared after reload and in a clean browser session. Code clues support observed behaviour; they are not proof by themselves.</p>${artifactSummary}${items.length?items.map(item=>`<article class="goal"><div class="goal-head"><div><h3>${escapeHtml(title(item.category))}</h3><small>${escapeHtml(item.dark_pattern_category?`Parent taxonomy: ${title(item.dark_pattern_category)} · `:'')}${escapeHtml(item.element||'Page-level evidence')}</small></div><div>${badge(item.status)} ${badge(item.severity)}</div></div><p>${escapeHtml(item.rationale)}</p><div class="metrics">${metric('Score',`${number(item.score)}/100`)}${metric('Confidence',`${Math.round(item.confidence*100)}%`)}${metric('Initial',item.initial_value||'—')}${metric('Observed',item.observed_value||'—')}${metric('Reload',item.after_reload||'—')}${metric('Clean session',item.clean_session_value||'—')}</div><div>${(item.evidence||[]).map(x=>`<div class="limitation"><b>Observed evidence</b>${escapeHtml(x)}</div>`).join('')}${(item.counter_evidence||[]).map(x=>`<div class="conf"><b>Counter-evidence</b>${escapeHtml(x)}</div>`).join('')}</div><div class="tags">${(item.bert_categories||[]).map(x=>`<span class="badge low">BERT: ${escapeHtml(title(x))}</span>`).join('')}${(item.visual_cues||[]).map(x=>`<span class="badge low">YOLO: ${escapeHtml(title(x))}</span>`).join('')}</div>${(item.timeline||[]).length?`<details><summary>Behaviour timeline</summary>${item.timeline.map(sample=>`<div class="edge">${number(sample.elapsed_ms/1000)}s · ${escapeHtml(title(sample.event))} · ${escapeHtml(sample.value)}</div>`).join('')}</details>`:''}${(item.code_evidence||[]).length?`<details><summary>Relevant redacted code evidence</summary>${item.code_evidence.map(code=>`<p><small>${escapeHtml(title(code.source))}${code.asset_url?` · ${escapeHtml(code.asset_url)}`:''} · SHA-256 ${escapeHtml(code.sha256||'unavailable')}</small></p><pre style="white-space:pre-wrap;word-break:break-word;background:#101828;color:#e4e7ec;padding:12px;border-radius:8px;max-height:220px;overflow:auto">${escapeHtml(code.excerpt)}</pre>`).join('')}</details>`:''}${(item.screenshot_paths||[]).slice(0,4).map(path=>`<img class="evidence-shot" data-shot="${escapeHtml(path)}" alt="Redacted behavioural evidence screenshot">`).join('')}</article>`).join(''):'<div class="empty">No dynamic frontend candidate was found during the bounded observation.</div>'}`}
    function renderLimitations(items,root){root.innerHTML=items.map(x=>`<div class="limitation"><b>${escapeHtml(title(x.code))}${x.phase?` · ${escapeHtml(title(x.phase))}`:''}</b>${escapeHtml(x.message)}${x.recoverable?' · This run may be resumed.':''}</div>`).join('')}
    function renderGoal(goal){const finding=goal.overall_finding,conf=goal.confidence_gate;const mechanisms=(goal.mechanism_findings||[]).filter(x=>x.status==='detected');const review=conf.review!=='not_needed'&&finding.finding_id?renderReviewForm(finding):'';return `<article class="goal"><div class="goal-head"><div><h3>${escapeHtml(goal.label)}</h3><small>${escapeHtml(title(goal.family))} · signature ${escapeHtml(goal.signature)}</small></div><div>${badge(finding.status)} ${badge(finding.severity)} ${badge(conf.gate)}</div></div><p>${escapeHtml(finding.rationale)}</p><div class="metrics">${metric('Finding score',`${number(finding.score)}/100`)}${metric('Finding confidence',`${Math.round(finding.confidence*100)}%`)}${metric('Pairing confidence',`${Math.round(goal.pairing_confidence*100)}%`)}</div><div class="tags">${mechanisms.length?mechanisms.map(x=>badge(x.category)).join(''):'<span class="badge none">No mechanism detected</span>'}</div><div class="goal-grid">${renderPath(goal.acquisition)}${renderPath(goal.exit)}</div>${renderConfidence(conf)}${goal.limitations?.length?`<h3>Goal limitations</h3>${goal.limitations.map(x=>`<div class="limitation">${escapeHtml(x.message)}</div>`).join('')}`:''}${review}</article>`}
    function renderPath(path){const terminal=path.terminal||{};return `<section class="path"><div class="goal-head"><b>${escapeHtml(title(path.phase))}</b>${badge(path.status)}</div><div class="metrics">${metric('Effort',number(path.metrics?.effort_score))}${metric('Actions',path.metrics?.meaningful_actions??0)}${metric('Fields',path.metrics?.form_fields??0)}</div><small>Terminal evidence: ${terminal.verified?'verified':terminal.commit_frontier?'safe commit frontier':'not verified'} · ${Math.round((terminal.confidence||0)*100)}%</small><div class="timeline">${(path.steps||[]).map(step=>`<div class="step"><b>${escapeHtml(step.description||step.action)}</b><small>${escapeHtml(step.action)} · ${escapeHtml(step.status)} · ${step.duration_ms||0} ms</small><small>${escapeHtml(step.url_after||'')}</small><div class="tags">${(step.evidence?.obstruction_tags||[]).map(badge).join('')}${(step.evidence?.bert_categories||[]).map(x=>`<span class="badge low">BERT: ${escapeHtml(title(x))}</span>`).join('')}${(step.evidence?.visual_cues||[]).map(x=>`<span class="badge low">YOLO: ${escapeHtml(title(x))}</span>`).join('')}</div>${step.screenshot_path?`<img class="evidence-shot" data-shot="${escapeHtml(step.screenshot_path)}" alt="Redacted evidence screenshot">`:''}</div>`).join('')||'<div class="empty">No executable steps recorded.</div>'}</div></section>`}
    function renderConfidence(conf){const dimensions=[['Goal equivalence',conf.goal_equivalence],['Acquisition terminal',conf.acquisition_terminal],['Exit terminal',conf.exit_terminal],['Replay stability',conf.replay_stability],['Selector stability',conf.selector_stability],['Evidence quality',conf.evidence_quality]];return `<h3>Confidence gate ${badge(conf.review)}</h3><div class="confidence">${dimensions.map(([label,value])=>`<div class="conf">${escapeHtml(label)}<b>${Math.round((value||0)*100)}%</b></div>`).join('')}</div>${(conf.reasons||[]).map(x=>`<small>• ${escapeHtml(x)}</small>`).join('<br>')}${(conf.caps||[]).map(x=>`<div class="limitation"><b>Confidence cap</b>${escapeHtml(x)}</div>`).join('')}`}
    function renderReviewForm(finding){return `<div class="review-box" data-finding="${escapeHtml(finding.finding_id)}"><b>Reviewer decision required</b><div class="review-fields"><label>Decision<select class="review-decision"><option value="needs_review">Needs review</option><option value="confirmed">Confirm evidence</option><option value="rejected">Reject finding</option></select></label><label>Severity<select class="review-severity"><option value="none">None</option><option value="low">Low</option><option value="medium">Medium</option><option value="high" ${finding.severity==='high'?'selected':''}>High</option></select></label><label>Notes<textarea class="review-notes" rows="2" placeholder="Evidence-based review note"></textarea></label></div><button type="button" onclick="saveFindingReview(this)">Save review</button><span class="statusline review-status"></span></div>`}
    async function saveFindingReview(button){const box=button.closest('.review-box'),status=box.querySelector('.review-status');try{await api(`/api/v1/autonomous-findings/${box.dataset.finding}/review`,{method:'PUT',body:JSON.stringify({decision:box.querySelector('.review-decision').value,severity:box.querySelector('.review-severity').value,notes:box.querySelector('.review-notes').value})});status.textContent=' Review saved';loadReviewQueue()}catch(error){showError(status,error)}}
    function renderGraph(graph){const phases=['acquisition','session','exit'];const nodes=graph.nodes||[],edges=graph.edges||[];$('graph').innerHTML=nodes.length?`<div class="graph-lanes">${phases.map(phase=>`<section class="lane"><h4>${escapeHtml(phase)} · ${nodes.filter(n=>n.phase===phase).length} states</h4>${nodes.filter(n=>n.phase===phase).map(node=>`<div class="node"><b>${escapeHtml(node.title||'Untitled state')}</b><small>${escapeHtml(node.url)}</small><small>${escapeHtml(node.state_id)} · depth ${node.depth}</small>${node.screenshot_path?`<img class="evidence-shot" data-shot="${escapeHtml(node.screenshot_path)}" alt="Redacted state screenshot">`:''}${edges.filter(e=>e.source_state_id===node.state_id).map(e=>`<div class="edge">${escapeHtml(e.accessible_name||e.action)} → ${escapeHtml(e.target_state_id||title(e.status))} ${badge(e.risk)}</div>`).join('')}</div>`).join('')||'<div class="empty">No states</div>'}</section>`).join('')}</div>`:'<div class="empty">No graph was produced.</div>'}
    async function hydrateScreenshots(root,runId){for(const image of root.querySelectorAll('img[data-shot]')){const filename=String(image.dataset.shot||'').split(/[\\/]/).pop();if(!filename)continue;try{const response=await fetch(`/api/v1/autonomous-flow-runs/${encodeURIComponent(runId)}/screenshots/${encodeURIComponent(filename)}`,{headers:{Authorization:`Bearer ${token}`}});if(!response.ok)throw new Error('Screenshot unavailable');image.src=URL.createObjectURL(await response.blob())}catch{image.replaceWith(Object.assign(document.createElement('small'),{textContent:'Redacted screenshot unavailable'}))}}}

    async function openRun(id){currentRun=id;window.scrollTo({top:0,behavior:'smooth'});try{const job=await api(`/api/v1/autonomous-flow-runs/${id}`);updateProgress(job);if(job.result)renderResult(job.result);if(['queued','running'].includes(job.status)){ $('cancelButton').classList.remove('hidden');schedulePoll()}if(job.status==='needs_input')configureInput(job.result)}catch(error){showError($('runStatus'),error)}}
    async function loadHistory(){try{const jobs=await api('/api/v1/autonomous-flow-runs?limit=30');completedRuns=jobs.filter(x=>x.status==='completed'&&x.result);$('historyList').innerHTML=jobs.length?jobs.map(job=>`<article class="history-row"><div><p><b>${escapeHtml(job.request.url)}</b> ${badge(job.status)}</p><small>${escapeHtml(job.run_id)} · ${escapeHtml(title(job.stage))} · ${new Date(job.created_at).toLocaleString()} · ${escapeHtml(job.request.goal_families.map(title).join(', '))}</small></div><button type="button" class="ghost" onclick="openRun('${escapeHtml(job.run_id)}')">Open</button></article>`).join(''):'<div class="empty">No autonomous runs yet.</div>';populateComparisonRuns()}catch(error){$('historyList').innerHTML=`<div class="empty">${escapeHtml(error.message)}</div>`}}
    function populateComparisonRuns(){for(const id of ['baselineRun','candidateRun']){const select=$(id),selected=select.value;select.innerHTML=`<option value="">Select ${id==='baselineRun'?'baseline':'candidate'}</option>`+completedRuns.map(job=>`<option value="${escapeHtml(job.run_id)}">${escapeHtml(job.request.url)} · ${escapeHtml(job.run_id.slice(0,8))}</option>`).join('');select.value=selected}}
    async function compareRuns(){const baseline=$('baselineRun').value,candidate=$('candidateRun').value;if(!baseline||!candidate){showError($('compareStatus'),new Error('Select both a baseline and candidate run.'));return}if(baseline===candidate){showError($('compareStatus'),new Error('Choose two different runs.'));return}try{$('compareStatus').textContent='Comparing flow and dynamic frontend evidence…';const result=await api('/api/v1/autonomous-flow-comparisons',{method:'POST',body:JSON.stringify({baseline_run_id:baseline,candidate_run_id:candidate})});$('compareStatus').textContent=`Comparison ${result.comparison_id}`;$('comparison').innerHTML=`<article class="compare-result"><h3>${badge(result.verdict)} Confidence ${Math.round(result.confidence*100)}%</h3>${(result.warnings||[]).map(x=>`<div class="limitation">${escapeHtml(x)}</div>`).join('')}${(result.goal_regressions||[]).map(g=>`<div class="step"><b>${escapeHtml(g.signature)} ${badge(g.verdict)}</b><p>${escapeHtml(g.rationale)}</p><small>Acquisition Δ ${number(g.acquisition_effort_delta)} · Exit Δ ${number(g.exit_effort_delta)} · Ratio Δ ${number(g.effort_ratio_delta)}</small><div>${(g.added_mechanisms||[]).map(x=>`<span class="badge high">Added: ${escapeHtml(title(x))}</span>`).join('')}${(g.resolved_mechanisms||[]).map(x=>`<span class="badge none">Resolved: ${escapeHtml(title(x))}</span>`).join('')}</div></div>`).join('')}${(result.behavior_regressions||[]).map(g=>`<div class="step"><b>${escapeHtml(title(g.category))} ${badge(g.verdict)}</b><p>${escapeHtml(g.rationale)}</p><small>${escapeHtml(title(g.baseline_status))} → ${escapeHtml(title(g.candidate_status))}</small></div>`).join('')}${!(result.goal_regressions||[]).length&&!(result.behavior_regressions||[]).length?'<div class="empty">No comparable evidence.</div>':''}</article>`}catch(error){showError($('compareStatus'),error)}}

    async function loadReviewQueue(){try{const items=await api('/api/v1/autonomous-flow-review-queue?limit=50');$('reviewQueue').innerHTML=items.length?items.map(item=>{const finding=item.finding||item;const runId=item.run_id||finding.run_id||'';return `<article class="queue-row"><div class="goal-head"><div><b>${escapeHtml(item.goal_label||title(finding.category))}</b><small> · ${escapeHtml(item.target_url||'')} · run ${escapeHtml(runId)}</small><p>${escapeHtml(finding.rationale||'Candidate evidence needs review.')}</p></div>${badge(item.review_recommendation||finding.severity||'none')}</div>${finding.finding_id||finding.id?renderReviewForm({...finding,finding_id:finding.finding_id||finding.id}):''}</article>`}).join(''):'<div class="empty">No confidence-gated findings are waiting for review.</div>'}catch(error){$('reviewQueue').innerHTML=`<div class="empty">${escapeHtml(error.message)}</div>`}}
    async function runManual(path){try{const job=await api(path,{method:'POST'});$('manualStatus').textContent=`Legacy benchmark queued: ${job.run_id}. View its result through the manual API.`}catch(error){showError($('manualStatus'),error)}}

    function loadBehaviorPreset(url){$('targetUrl').value=url;$('runMode').value='controlled';$('goalFamily').value='auto';$('analyseBehavior').checked=true;$('behaviorSeconds').value='10';window.scrollTo({top:0,behavior:'smooth'});$('runStatus').textContent='Benchmark loaded. Click Analyze website.'}
    $('loginButton').onclick=()=>authenticate('login');$('registerButton').onclick=()=>authenticate('register');$('logoutButton').onclick=()=>logout();$('runForm').onsubmit=startRun;$('cancelButton').onclick=cancelRun;$('resumeButton').onclick=resumeRun;$('refreshResultButton').onclick=()=>currentRun&&openRun(currentRun);$('refreshHistoryButton').onclick=loadHistory;$('refreshQueueButton').onclick=loadReviewQueue;$('compareButton').onclick=compareRuns;document.querySelectorAll('.manual-preset').forEach(button=>button.onclick=()=>runManual(button.dataset.path));document.querySelectorAll('.behavior-preset').forEach(button=>button.onclick=()=>loadBehaviorPreset(button.dataset.url));if(token)enterWorkspace();
  </script>
</body>
</html>"""
    )
